import{_ as e,o,c as t,a2 as r}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Atajos de teclado","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/hotkeys.md","filePath":"es-ES/user-guide/hotkeys.md","lastUpdated":1786082398000}'),n={name:"es-ES/user-guide/hotkeys.md"};function d(i,a,l,s,c,u){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="atajos-de-teclado" tabindex="-1">Atajos de teclado <a class="header-anchor" href="#atajos-de-teclado" aria-label="Permalink to &quot;Atajos de teclado&quot;">​</a></h1><p>Todos los atajos globales y de la aplicación que aparecen a continuación se pueden reasignar desde <strong>Configuración → Atajos</strong>; aquí se muestran los valores predeterminados. Ver <a href="./settings/hotkeys-page.html">Configuración → Página de atajos</a> para la propia interfaz de configuración.</p><h2 id="atajos-globales" tabindex="-1">Atajos globales <a class="header-anchor" href="#atajos-globales" aria-label="Permalink to &quot;Atajos globales&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Acción</th><th>Predeterminado</th><th>Notas</th></tr></thead><tbody><tr><td>Mostrar/ocultar ventana rápida</td><td>Doble pulsación de <code>Ctrl</code></td><td>También se puede configurar como una combinación completa (por ejemplo, <code>Alt+Espacio</code>) en lugar de una doble pulsación.</td></tr><tr><td>Cambio rápido</td><td><code>Ctrl+G</code></td><td>En un diálogo de archivos compatible, navega a la última carpeta obtenida de un gestor de archivos compatible o del Panel Rápido. Una consulta en línea vacía también muestra ese destino como resultado.</td></tr><tr><td>Seleccionar elemento siguiente</td><td><code>Ctrl+N</code></td><td>También funciona como la flecha Abajo literal. En el <a href="./settings/quick-panel.html">Panel Rápido</a> recorre la pestaña entera y no un solo grupo: al final de uno continúa en el siguiente.</td></tr><tr><td>Seleccionar elemento anterior</td><td><code>Ctrl+P</code></td><td>También funciona como la flecha Arriba literal. En el Panel Rápido recorre igualmente la pestaña entera, cruzando de un grupo al siguiente.</td></tr><tr><td>Saltar al resultado 1–9</td><td><code>Ctrl</code> + dígito</td><td>El modificador es configurable; el dígito siempre es 1–9. La ventana rápida muestra el atajo de cada resultado visible como una pequeña insignia junto a él, así no tienes que contar filas.</td></tr><tr><td>Abrir menú de acciones</td><td><code>Ctrl+O</code></td><td>También funciona como la flecha Derecha literal sobre un resultado seleccionado.</td></tr><tr><td>Completar desde la selección</td><td><code>Ctrl+Tab</code></td><td>En la ventana rápida, rellena el cuadro de búsqueda con el nombre/ruta del resultado seleccionado.</td></tr><tr><td>Vista previa QuickLook</td><td><code>Alt+P</code></td><td>Alterna el panel de vista previa para el resultado seleccionado. El <a href="./settings/quick-panel.html">Panel Rápido</a> usa la misma tecla, y acopla la vista previa al lado suyo donde haya sitio.</td></tr><tr><td>Historial de palabras clave anterior</td><td><code>Alt+Arriba</code></td><td>Recorre hacia atrás tus consultas escritas recientemente.</td></tr><tr><td>Historial de palabras clave siguiente</td><td><code>Alt+Abajo</code></td><td>Recorre hacia delante tus consultas escritas recientemente.</td></tr><tr><td>Eliminar entrada del historial de palabras clave</td><td><code>Ctrl+Supr</code></td><td></td></tr><tr><td>Abrir ventana completa</td><td><em>(ninguno)</em></td><td>Abre la ventana completa directamente, trasladando la consulta actual — el mismo efecto que hacer clic izquierdo en el <a href="#icono-del-logotipo-en-el-cuadro-de-busqueda">propio logotipo de la ventana rápida</a> y elegir Mostrar ventana principal en el menú que se abre, sin ese paso adicional. No asignado por defecto; configura uno desde <strong>Configuración → Atajos</strong>.</td></tr><tr><td>Mantener la ventana abierta</td><td><code>Ctrl+T</code></td><td>Impide que la ventana se oculte cuando el foco se va a otro sitio, para poder componer una consulta con texto copiado de otras ventanas: al ocultarse, el cuadro de búsqueda se vaciaría cada vez. Dura lo que dure la invocación actual y termina al ocultarse. En la ventana rápida, un clic con el botón central en el logotipo hace lo mismo, y el logotipo se ilumina mientras está activo; pulsar la tecla de invocación mientras está visible pero sin foco lo devuelve al frente en lugar de ocultarlo. El <a href="./settings/quick-panel.html">Panel Rápido</a> usa la misma tecla, con su propio botón de anclaje como indicador visible.</td></tr><tr><td>Mostrar/ocultar el Panel Rápido</td><td><code>Ctrl+F2</code></td><td>Abre el <a href="./settings/quick-panel.html">Panel Rápido</a> acoplado en la esquina inferior derecha de la ventana que esté en primer plano, o lo cierra si ya está abierto. Una vez abierto, mantener el modificador de &quot;saltar al resultado 1–9&quot; y pulsar 1–9 cambia de espacio de trabajo.</td></tr></tbody></table><h2 id="icono-del-logotipo-en-el-cuadro-de-busqueda" tabindex="-1">Icono del logotipo en el cuadro de búsqueda <a class="header-anchor" href="#icono-del-logotipo-en-el-cuadro-de-busqueda" aria-label="Permalink to &quot;Icono del logotipo en el cuadro de búsqueda&quot;">​</a></h2><p>El pequeño icono del logotipo en el cuadro de búsqueda (a la izquierda o a la derecha, según la ventana) hace algo distinto en cada una de las <a href="./getting-started.html#las-tres-ventanas">tres ventanas</a>:</p><ul><li><p><strong>Ventana rápida</strong> — un clic izquierdo (sin arrastrar) abre el mismo menú que muestra el clic derecho del icono de la bandeja del sistema (Mostrar ventana principal, Alternar atajos, Configuración, Acerca de, Salida limpia, Salir), anclado en el cursor; el elemento Mostrar ventana principal de ese menú también traslada cualquier consulta que tengas escrita en ese momento. Hacer clic y arrastrar mueve la ventana, igual que arrastrar cualquier otra parte de la barra de búsqueda — mantén pulsado <strong>Ctrl</strong> mientras arrastras (ya sea la barra o el logotipo, y alternar Ctrl a mitad del arrastre también funciona) para restringir el movimiento solo a vertical, útil para ajustar la ventana arriba o abajo sin desplazarla lateralmente. El clic derecho restablece la ventana a su posición predeterminada en pantalla (no el tamaño) — la misma en la que se centra en el primer arranque. Un tooltip al pasar el cursor detalla los tres comportamientos.</p><p>La posición recordada es relativa al monitor en el que estuvo la ventana por última vez, no una coordenada absoluta de pantalla — invócala de nuevo en un monitor distinto (o uno con una resolución o escala de PPP diferente) y se reabrirá en el punto equivalente ahí en lugar de terminar potencialmente fuera de pantalla o en la pantalla equivocada.</p></li><li><p><strong>Ventana en línea</strong> — solo se puede pulsar cuando la ventana está acoplada a un diálogo nativo de Abrir/Guardar/Examinar carpetas: un clic izquierdo abre la <a href="#navegacion-rapida-raton">navegación rápida</a>, igual que el disparador dedicado de abajo. No se puede pulsar cuando está acoplada a una ventana normal del Explorador o al escritorio, ya que en ese caso no hay nada útil a lo que navegar — tampoco aparece ningún resaltado al pasar el cursor ni ningún tooltip, así que permanece discreto en lugar de parecer pulsable sin hacer nada.</p></li><li><p><strong>Ventana principal</strong> — ahí el logotipo es puramente decorativo; hacer clic en él no hace nada.</p></li></ul><h2 id="navegacion-rapida-raton" tabindex="-1">Navegación rápida (ratón) <a class="header-anchor" href="#navegacion-rapida-raton" aria-label="Permalink to &quot;Navegación rápida (ratón)&quot;">​</a></h2><p>El clic central está activado por defecto y el doble clic está desactivado por defecto. Cada disparador se puede cambiar por separado en la configuración:</p><ul><li>Cuando actives este disparador, un <strong>doble clic</strong> en un espacio vacío del escritorio o dentro de una ventana del Explorador activa la navegación rápida.</li><li><strong>Clic central</strong> en un espacio vacío del escritorio o dentro de una ventana del Explorador — o en el panel de lista de archivos de un gestor de archivos de terceros compatible (Directory Opus, Total Commander, XYplorer, Files, ...), o en un diálogo nativo de Abrir/Guardar/Examinar carpetas — activa la navegación rápida. Esas otras ventanas solo responden al clic central: hacer doble clic ahí ya significa &quot;abrir esto&quot;, así que el doble clic no se reutiliza. Ver <a href="./file-manager-support.html">Gestores de archivos compatibles</a> para saber qué cubre cada integración.</li><li>Cuando la ventana de búsqueda en línea está acoplada a un diálogo nativo de Abrir/Guardar/Examinar carpetas, su propio logotipo también activa la navegación rápida — ver <a href="#icono-del-logotipo-en-el-cuadro-de-busqueda">Icono del logotipo en el cuadro de búsqueda</a> más arriba.</li></ul><p>Cualquiera de estos disparadores abre un menú en cascada con tus Favoritos, Historial y carpetas de acceso rápido configuradas (ver <a href="./settings/favorites.html">Configuración → Favoritos</a> y <a href="./settings/history.html">Configuración → Historial</a>) — los plugins también pueden aportar sus propias entradas, como la propia lista de carpetas favoritas (Directory Hotlist) de Total Commander si has configurado una en <code>wincmd.ini</code>, el propio menú de Favoritos de Directory Opus, o un <a href="./instant-answers.html#comandos-personalizados">Comando personalizado</a> marcado como &quot;Mostrar en Navegación rápida&quot; (anidado opcionalmente en un submenú dándole una ruta separada por <code>/</code>). Cada plugin que contribuye obtiene su propia sección etiquetada en la raíz del menú, y el orden en que aparecen esas secciones lo defines tú — ver <a href="./settings/general.html#navegacion-rapida">Configuración → General → Navegación rápida</a>. Hacer clic en una carpeta navega hasta ella en la ventana de destino; hacer clic en un archivo también navega hasta ahí, situándose sobre el archivo seleccionado dentro de su carpeta contenedora en lugar de abrirlo — la única excepción es el escritorio, que no tiene un panel de ventana existente en el que navegar, así que ahí una carpeta o archivo se abre directamente, igual que haría un doble clic. Dentro de un diálogo de archivos en concreto, hacer clic en un archivo en su lugar salta el diálogo a la carpeta de ese archivo — deliberadamente nunca confirma Abrir/Guardar en tu nombre.</p><p>El plugin <strong>Folder Cascader</strong> es el que realmente construye este menú. Además de Favoritos e Historial (cada uno activable de forma independiente), tiene su propia lista configurable de carpetas de acceso rápido — desde <strong>Configuración → Plugins → Folder Cascader → Configurar</strong>, añade la ruta de una carpeta y un nombre para mostrar opcional, y dale un valor de <strong>Submenú</strong> (por ejemplo, <code>Herramientas/Red</code>, separado por <code>/</code> para varios niveles) para anidarla bajo una categoría en lugar de mostrarla en la raíz. Cada nivel del menú — la raíz y cualquier categoría anidada — también tiene un pequeño botón <strong>+</strong> en su propio encabezado: haz clic en él para añadir ahí mismo la carpeta que estás explorando en ese momento, rellenada de antemano con su nombre, ruta y la propia ruta de submenú de ese nivel (todo aún editable antes de confirmar), sin salir del menú para abrir Configuración.</p><h2 id="teclas-fijas-no-configurables" tabindex="-1">Teclas fijas (no configurables) <a class="header-anchor" href="#teclas-fijas-no-configurables" aria-label="Permalink to &quot;Teclas fijas (no configurables)&quot;">​</a></h2><p>Estas siempre se comportan de la misma forma sin importar tu configuración de atajos:</p><table tabindex="0"><thead><tr><th>Tecla</th><th>Contexto</th><th>Comportamiento</th></tr></thead><tbody><tr><td><code>Escape</code></td><td>En cualquier lugar</td><td>Borra el cuadro de búsqueda si tiene texto; en caso contrario, cierra la ventana (o sale del menú de acciones).</td></tr><tr><td><code>Intro</code></td><td>Lista de resultados</td><td>Abre el resultado seleccionado.</td></tr><tr><td><code>Ctrl+Intro</code></td><td>Lista de resultados</td><td>Localiza el resultado en el Explorador en lugar de abrirlo.</td></tr><tr><td><code>Ctrl+Mayús+Intro</code></td><td>Lista de resultados</td><td>Abre el resultado elevado (Ejecutar como administrador).</td></tr><tr><td>Flecha <code>Izquierda</code> / <code>Derecha</code></td><td>Menú de acciones</td><td>Retroceden un nivel de menú / entran en un submenú.</td></tr><tr><td><code>Retroceso</code></td><td>Menú de acciones</td><td>Sale del menú de acciones cuando el cuadro de búsqueda ya está vacío.</td></tr><tr><td><code>Alt+Espacio</code> / <code>Alt+F4</code></td><td>Todas las ventanas propias de Lertaro</td><td><code>Alt+Espacio</code> se suprime en todas ellas: ninguna tiene una barra de título real a la que pueda pertenecer el menú de sistema de Windows. <code>Alt+F4</code> cierra la ventana principal y la de configuración con normalidad; sigue suprimido en las ventanas rápida, en línea y QuickLook y en los diálogos, que se muestran y se ocultan en lugar de abrirse y cerrarse.</td></tr></tbody></table><h2 id="atajos-de-accion-de-plugins" tabindex="-1">Atajos de acción de plugins <a class="header-anchor" href="#atajos-de-accion-de-plugins" aria-label="Permalink to &quot;Atajos de acción de plugins&quot;">​</a></h2><p>Los plugins pueden registrar sus propias acciones con un atajo predeterminado (por ejemplo, copiar ruta (<code>Ctrl+Mayús+C</code>), ejecutar como administrador, o las acciones de archivo integradas — Cortar <code>Ctrl+X</code>, Copiar <code>Ctrl+C</code>, Pegar <code>Ctrl+V</code>, Eliminar <code>Supr</code>, Eliminar permanentemente <code>Mayús+Supr</code>). Estos aparecen en <strong>Configuración → Atajos → Acciones de plugins</strong>, agrupados por el plugin que los registró, y se pueden reasignar de la misma forma que los atajos integrados.</p><h2 id="lista-negra-de-procesos" tabindex="-1">Lista negra de procesos <a class="header-anchor" href="#lista-negra-de-procesos" aria-label="Permalink to &quot;Lista negra de procesos&quot;">​</a></h2><p>Si los atajos globales de Lertaro interfieren con otra aplicación (un juego que capture la entrada de teclado en bruto, por ejemplo), añade ese proceso a la <strong>Lista negra de procesos</strong> — ver <a href="./settings/hotkeys-page.html#process-blacklist">Configuración → Página de atajos</a>. Mientras un proceso en la lista negra esté en primer plano, los atajos globales de Lertaro, la interceptación de pulsaciones de teclado y los disparadores de ratón de navegación rápida de arriba se dejan pasar todos sin intervenir.</p><p>Cualquier aplicación en primer plano que sea realmente de pantalla completa recibe automáticamente el mismo trato — no hace falta ninguna entrada en la lista negra. En cualquier caso, un diálogo de archivos activo siempre está exento, así que la navegación rápida sigue funcionando ahí.</p>',20)])])}const g=e(n,[["render",d]]);export{m as __pageData,g as default};
